import{a as t,b as o,aO as i,o as n,_ as s,s as a}from"./index-BiEBfu7W.js";const r={class:"campaign"},d={__name:"PrivacyView",setup(c){return(u,e)=>(n(),t("div",r,[o(s),e[0]||(e[0]=i('<main id="main-content" class="wrap utility-intro privacy-content"><p class="eyebrow">DIVERSIFIED HOME INSPECTIONS</p><h1>Your information.</h1><p>This notice describes information collected through our campaign landing page.</p><h2>When you request an inspection quote</h2><p> We collect the name, email address, phone number, and property or inspection details you provide. We use those details to respond to your request, prepare an estimate, and coordinate services. Submitting this form is a request for contact about your inspection. </p><h2>Campaign measurement</h2><p> Our production landing page uses Google Analytics and Meta Pixel to understand visits and actions such as quote requests and phone-link clicks. These providers may use cookies and similar technologies. Campaign parameters and advertising click identifiers may be stored for your browser session and included with your request so we can understand how you found us. </p><h2>Service providers</h2><p> Form information is transmitted through Zapier to support our office workflow. Inspection requests are reviewed by our team, who will follow up about scope, pricing and scheduling. The site does not generate or send an automatic customer quote. Our own analytics events do not include the name, email, phone number, or property address you enter in the form. </p><h2>Contact us</h2><p> For questions about your information, contact <a href="mailto:office@diversifiedhomeinspections.com">office@diversifiedhomeinspections.com</a> or call <a href="tel:+19542529980">(954) 252-9980</a>. </p><p> Diversified Home Inspections, Inc.<br>16201 SW 49th Street, Southwest Ranches, FL 33331 </p></main>',1)),o(a)]))}};export{d as default};
